{
  "private": true,
  "type": "module",
  "scripts": {
    "dev": "next dev",
    "build": "next build",
    "start": "next start"
  },
  "dependencies": {
    "next": "^16.3.0-canary.88",
    "react": "19.1.0",
    "react-dom": "19.1.0"
  },
  "devDependencies": {
    "@types/node": "^20",
    "@types/react": "^19",
    "@types/react-dom": "^19",
    "@vitejs/plugin-react": "^4.4.1",
    "typescript": "^5",
    "vite-tsconfig-paths": "^5.1.4",
    "vitest": "^3.1.3"
  }
}
import type { NextConfig } from 'next'

const nextConfig: NextConfig = {}

export default nextConfig
// Mock authentication library
// In a real app, this would verify session tokens, JWTs, etc.

export interface Session {
  userId: string
  role: 'user' | 'admin'
  name: string
}

// Simulates getting the current user's session
// Returns null if not authenticated
export async function getSession(): Promise<Session | null> {
  // For testing purposes, return a non-admin user
  return {
    userId: '123',
    role: 'user', // Not an admin
    name: 'John Doe',
  }
}

// Helper to check if user has admin role
export async function verifyAdmin(): Promise<{
  isAdmin: boolean
  session: Session | null
}> {
  const session = await getSession()
  return {
    isAdmin: session?.role === 'admin',
    session,
  }
}
import Link from 'next/link'

export default function Home() {
  return (
    <main>
      <h1>Welcome</h1>
      <p>This is the home page.</p>
      <Link href="/admin">Go to Admin Dashboard</Link>
    </main>
  )
}
import type { Metadata } from 'next'

export const metadata: Metadata = {
  title: 'Admin Dashboard',
  description: 'Admin area with auth protection',
}

export default function RootLayout({
  children,
}: Readonly<{
  children: React.ReactNode
}>) {
  return (
    <html lang="en">
      <body>{children}</body>
    </html>
  )
}
{
  "compilerOptions": {
    "target": "ES2017",
    "lib": ["dom", "dom.iterable", "esnext"],
    "allowJs": true,
    "skipLibCheck": true,
    "strict": true,
    "noEmit": true,
    "esModuleInterop": true,
    "module": "esnext",
    "moduleResolution": "bundler",
    "resolveJsonModule": true,
    "isolatedModules": true,
    "jsx": "react-jsx",
    "incremental": true,
    "plugins": [
      {
        "name": "next"
      }
    ],
    "paths": {
      "@/*": ["./*"]
    }
  },
  "include": ["next-env.d.ts", "**/*.ts", "**/*.tsx", ".next/types/**/*.ts"],
  "exclude": ["node_modules"]
}

